import{_ as a,o as t,c as o,a3 as n}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Documentation generator","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/docs/docs/index.md"},"headers":[],"relativePath":"tools/docs/docs/index.md","filePath":"tools/docs/docs/index.md","lastUpdated":1791428389000}'),i={name:"tools/docs/docs/index.md"};function d(r,e,s,c,p,m){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="documentation-generator" tabindex="-1">Documentation generator <a class="header-anchor" href="#documentation-generator" aria-label="Permalink to &quot;Documentation generator&quot;">​</a></h1><p><code>@pumpkin-plugins/docs</code> defines plugin metadata and generates repository documentation from the component sources. It reads plugin <code>src/info.ts</code>, command declarations, configuration schemas, package manifests, component guide files, and GitHub Action metadata rather than maintaining a separate component catalog.</p><h2 id="regenerate-repository-docs" tabindex="-1">Regenerate repository docs <a class="header-anchor" href="#regenerate-repository-docs" aria-label="Permalink to &quot;Regenerate repository docs&quot;">​</a></h2><p>Run <code>pnpm readme</code> after changing plugin information, command declarations, config schemas, action inputs or outputs, package metadata, or component guides. It updates generated README sections, component guide and API reference links, and the root package and action tables.</p><p>Run <code>pnpm readme:check</code> to verify that generated files are current without writing them. Keep the markers around generated README blocks in place. Change their source metadata or the Markdown outside generated blocks instead of editing generated content by hand.</p><h2 id="plugin-metadata" tabindex="-1">Plugin metadata <a class="header-anchor" href="#plugin-metadata" aria-label="Permalink to &quot;Plugin metadata&quot;">​</a></h2><p>Plugins declare their name, description, permissions, commands, compatibility notes, and config description as typed <code>PluginInfo</code>. The same declarations feed Pumpkin metadata and generated README tables, which helps keep runtime behavior and operator documentation aligned. Component guides live next to the package in <code>docs/</code>; the site discovers those pages and their navigation from the filesystem and component metadata.</p>',7)])])}const g=a(i,[["render",d]]);export{u as __pageData,g as default};
